def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
    for r, c in blocks:
        # Clockwise transfer of the four corner colors around each 2x2 block.
        coords = {
            'NW': (r - 1, c - 1), 'NE': (r - 1, c + 2),
            'SW': (r + 2, c - 1), 'SE': (r + 2, c + 2),
        }
        colors = {k: grid[rr][cc] for k, (rr, cc) in coords.items() if 0 <= rr < h and 0 <= cc < w}
        rays = {'NW': (-1, -1, 'SW'), 'NE': (-1, 1, 'NW'),
                'SW': (1, -1, 'SE'), 'SE': (1, 1, 'NE')}
        for key, (dr, dc, source) in rays.items():
            rr, cc = coords[key]
            if source not in colors:
                continue
            color = colors[source]
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out

